// The inline render path must render a slot, and import what it calls.
//
// A component that projects through a slot depends on two things in the same place.
//
// 1. `generateInlineNodes`'s `walk` needs a case for `slot-template`: without one, a
//    `default: break;` drops a `<slot name="item" let:label>` written inside a component's tag from
//    the emitted module, silently, which is what a default branch over a node-type union buys you.
//
// 2. The module imports what it calls. The hoisted slot function was generated by the template
//    path, and a module that called `html` without importing it threw
//    `ReferenceError: html is not defined`. Since #364 the slot's body is built by the inline path
//    too, so a module with a slot calls no `html` and imports none.
//
// The assertions below are the two halves plus the control: a component with no slot does not
// carry the import either.

import { describe, it, expect } from 'vitest';
import { compile } from '../src/plugin';

const SLOTTED = `<template>
  <pdx-select label="Team member" :options="people" labelField="name" valueField="id">
    <slot name="item" let:label let:raw>
      <span class="who">{{ label }}</span>
    </slot>
  </pdx-select>
</template>

<script setup>
const people = [{ id: 1, name: 'Ada' }];
</script>`;

const PLAIN = `<template><p :title="t">{{ t }}</p></template>
<script setup>
@prop t: string = '';
</script>`;

const emitted = (source: string): string =>
    compile(source, 'list.pdx', [], undefined, { production: true }).code;

/** The names the module imports from `@pdxui/core`. */
function importedNames(code: string): string[] {
    const m = /import\s*\{([^}]*)\}\s*from\s*'@pdxui\/core'/.exec(code);
    return m ? m[1].split(',').map(s => s.trim()).filter(Boolean) : [];
}

describe('a scoped slot survives the inline path', () => {
    it('the slot reaches the emitted module', () => {
        const code = emitted(SLOTTED);
        expect(code, 'the slot was dropped from the render').toContain("slotCarrier('item'");
        expect(importedNames(code), 'slotCarrier is called and not imported').toContain('slotCarrier');
    });

    it('its body is there too, not just the carrier', () => {
        // A carrier with an empty function renders nothing, and would satisfy the assertion above.
        expect(emitted(SLOTTED), 'the slot function has no body').toContain('who');
    });

    it('and it is attached to something, not created and forgotten', () => {
        // It takes the place of its marker in the block's copied markup (#109).
        expect(emitted(SLOTTED), 'the carrier was built and never put in place')
            .toMatch(/__m\d+\.replaceWith\(slotCarrier\('item'/);
    });
});

describe('the module imports what it calls', () => {
    it('a slot body is built inline, so the module neither calls nor imports html (#364)', () => {
        const code = emitted(SLOTTED);
        expect(code, 'the hoisted slot still uses html``').not.toMatch(/html`/);
        expect(importedNames(code), 'an unused html import').not.toContain('html');
        // Its body uses what the inline path imports for it: the text binding.
        expect(importedNames(code)).toContain('bindInterpolation');
    });

    it('and a component with no slot does not import html either', () => {
        const code = emitted(PLAIN);
        expect(code).not.toMatch(/html`/);
        expect(importedNames(code), 'an unused html import came back').not.toContain('html');
    });
});

describe('and the emitted module parses', () => {
    it('with a slot in it', () => {
        // `new Function` is a parser that is already here. The import lines are stripped because an
        // import statement is illegal in a function body; the body is never called, only compiled.
        const body = emitted(SLOTTED).replace(/^\s*import\b.*$/gm, '');
        expect(() => new Function(body)).not.toThrow();
    });
});
